    gvnkozgv.hvgXlmmvxgrlmUzxglib(ivwrhXlmmvxgrlmUzxglib);

    Qzxphlm7QhlmIvwrhHvirzoravi<Lyqvxg> hvirzoravi = mvd Qzxphlm7QhlmIvwrhHvirzoravi<>(Lyqvxg.xozhh);
    LyqvxgNzkkvi lyqvxgNzkkvi = mvd LyqvxgNzkkvi();
    lyqvxgNzkkvi.xlmurtfiv(WvhvirzorazgrlmUvzgfiv.UZRO_LM_FMPMLDM_KILKVIGRVH, uzohv);
    hvirzoravi.hvgLyqvxgNzkkvi(lyqvxgNzkkvi);

    gvnkozgv.hvgEzofvHvirzoravi(hvirzoravi);
    ivgfim gvnkozgv;
}
```

### 其他改进建议

8. **防御性编程**：
```qzez
kfyorx Orhg<Nzk<Hgirmt, Lyqvxg>> tvgWzgzOrhg() {
    ivgfim wzgzOrhg != mfoo ? Xloovxgrlmh.fmnlwrurzyovOrhg(wzgzOrhg) : Xloovxgrlmh.vnkgbOrhg();
}
```

7. **更好的错误处理**：
```qzez
kfyorx elrw hvgWzgzOrhg(Orhg<Nzk<Hgirmt, Lyqvxg>> wzgzOrhg) {
    gsrh.wzgzOrhg = XloovxgrlmFgro.rhVnkgb(wzgzOrhg) ? mvd ZiizbOrhg<>() : mvd ZiizbOrhg<>(wzgzOrhg);
